	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "nazanfeyzioglu_order_item_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"orderId" integer NOT NULL,
	"itemType" varchar(16) NOT NULL,
	"printId" integer,
	"workId" integer,
	"itemTitle" varchar(256) NOT NULL,
	"quantity" integer NOT NULL,
	"unitAmount" integer NOT NULL,
	"amountTotal" integer NOT NULL,
	CONSTRAINT "order_item_quantity_positive" CHECK (quantity > 0),
