-- Move every existing single-item order into its own order_item row before the
-- legacy line columns are dropped. Legacy orders never had tax, so the line
-- total is quantity x unit price and anything above that was shipping.
INSERT INTO "nazanfeyzioglu_order_item" ("orderId", "itemType", "printId", "workId", "itemTitle", "quantity", "unitAmount", "amountTotal")
SELECT "id", "itemType", "printId", "workId", "itemTitle", "quantity", "unitAmount", "quantity" * "unitAmount"
FROM "nazanfeyzioglu_order";--> statement-breakpoint
