ALTER TABLE "nazanfeyzioglu_order" ADD COLUMN "amountShipping" integer DEFAULT 0 NOT NULL;--> statement-breakpoint
UPDATE "nazanfeyzioglu_order"
SET "amountSubtotal" = "quantity" * "unitAmount",
    "amountShipping" = GREATEST("amountTotal" - "quantity" * "unitAmount", 0);--> statement-breakpoint
